import type { ChannelConfig, ChannelId } from "@bix/config";
import type { Database } from "@bix/storage";
import type { PlanSlot } from "./types.js";

/**
 * Feature slots are the third content type (alongside event and competitor):
 * one "feature demo" per app-UI screenshot per channel. Unlike the monthly
 * scan, they are NOT generated by the model — they are enumerated directly from
 * the brand screenshots the owner dropped in, so adding a screenshot adds a
 * feature to show off.
 *
 * These rows are written with a fixed `month = "feature"` marker and
 * month-independent ids (`feature-<channel>-<NN>`) so they live beside the
 * scan's dated slots without colliding. Crucially, {@link insertFeatureSlots}
 * does NOT delete by month the way {@link ContentPlanStore.save} does, so a
 * later competitor scan can't wipe the feature catalogue and vice-versa.
 */

/** Fixed month marker for feature rows (kept out of any real YYYY-MM scan). */
export const FEATURE_MONTH = "feature";

/**
 * Leading filename segments that name a channel/language rather than the
 * feature itself, dropped when deriving a topic (e.g. `01-spanish-learning-path`
 * → "Learning path"). Matched case-insensitively.
 */
const CHANNEL_WORDS: ReadonlySet<string> = new Set([
  "spanish",
  "global",
  "english",
  "french",
  "german",
  "es",
  "en",
]);

/** Last path segment of `path` (handles both `/` and `\` separators). */
function baseName(path: string): string {
  const slash = Math.max(path.lastIndexOf("/"), path.lastIndexOf("\\"));
  return slash >= 0 ? path.slice(slash + 1) : path;
}

/** Strip a trailing file extension (keeps dotfiles intact). */
function stripExt(name: string): string {
  const dot = name.lastIndexOf(".");
  return dot > 0 ? name.slice(0, dot) : name;
}

/**
 * Derive a human topic from a screenshot filename: drop the directory, the
 * extension and the leading `NN-` index, drop a leading channel/language word,
 * turn dashes/underscores into spaces, and capitalise the first letter. E.g.
 * `assets/brand/screenshots/07-spanish-picture-matching.png` → "Picture matching".
 */
export function topicFromFilename(filename: string): string {
  let stem = stripExt(baseName(filename));
  stem = stem.replace(/^\d+[-_]?/, "");
  let parts = stem.split(/[-_]+/).filter((p) => p.length > 0);
  if (parts.length > 1 && CHANNEL_WORDS.has(parts[0]!.toLowerCase())) {
    parts = parts.slice(1);
  }
  const words = parts.join(" ").trim();
  if (!words) return "App feature";
  return words.charAt(0).toUpperCase() + words.slice(1);
}

/** The leading numeric index of a screenshot filename (e.g. "07"), else "00". */
function extractNN(filename: string): string {
  const m = baseName(filename).match(/^(\d+)/);
  return m ? m[1]! : "00";
}

/** Stable, month-independent id for a feature slot: `feature-<channel>-<NN>`. */
export function featureSlotId(channelId: ChannelId, nn: string): string {
  return `feature-${channelId}-${nn}`;
}

/**
 * Build one feature-demo {@link PlanSlot} per screenshot per channel. The
 * screenshot path is stored verbatim in `assets[0]` (the orchestrator reads it
 * both as the writer's vision input and as the Wan app-screen reference); the
 * topic is derived from its filename. `date` is left empty (feature slots are
 * on-demand, not scheduled) and `time` defaults to the channel's posting time.
 */
export function buildFeatureSlots(
  screenshots: readonly string[],
  channels: readonly ChannelConfig[],
): PlanSlot[] {
  const slots: PlanSlot[] = [];
  for (const channel of channels) {
    for (const screenshot of screenshots) {
      slots.push({
        date: "",
        time: channel.posting.time,
        channel: channel.id,
        format: "Feature demo",
        source: "feature",
        topic: topicFromFilename(screenshot),
        brandFit: 8,
        hook: "",
        why: "Showcase of a Bix Learn app feature.",
        assets: [screenshot],
      });
    }
  }
  return slots;
}

/**
 * Insert (replace) feature slots directly into `plan_slots`, keyed by the
 * month-independent {@link featureSlotId}. Does NOT delete by month, so it never
 * disturbs the scan's dated slots. Returns the ids written, in order.
 */
export function insertFeatureSlots(
  db: Database,
  slots: readonly PlanSlot[],
  now: string = new Date().toISOString(),
): string[] {
  const ids: string[] = [];
  for (const slot of slots) {
    const nn = extractNN(slot.assets[0] ?? "");
    const id = featureSlotId(slot.channel, nn);
    db.run(
      `INSERT OR REPLACE INTO plan_slots
        (id, month, slot_date, slot_time, channel, format, source, topic, brand_fit, hook, why, assets, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        id,
        FEATURE_MONTH,
        slot.date,
        slot.time,
        slot.channel,
        slot.format,
        slot.source,
        slot.topic,
        slot.brandFit,
        slot.hook,
        slot.why,
        JSON.stringify(slot.assets),
        now,
      ],
    );
    ids.push(id);
  }
  return ids;
}
